mapper.update:
UPDATE SALES_MST MST SET STATUS = CASE WHEN COALESCE(VIRTUAL_YN, 'N') = 'Y' THEN '4' WHEN (SELECT COALESCE(SUM(CASE WHEN FR.STATUS = 'E' THEN 1 ELSE 0 END + CASE WHEN FM.RULE_CONTENTS IS NOT NULL THEN 0 ELSE 1 END), 1) FROM FCR_MST FM LEFT OUTER JOIN FCR_RESULT FR ON FR.FTA_CODE = FM.FTA_CODE AND FR.SALES_NO = FM.SALES_NO AND FR.SALES_SEQ = FM.SALES_SEQ AND FR.DIVISION_CODE = FM.DIVISION_CODE AND FR.COMPANY_CODE = FM.COMPANY_CODE WHERE FM.SALES_NO = MST.SALES_NO AND FM.DIVISION_CODE = MST.DIVISION_CODE AND FM.COMPANY_CODE = MST.COMPANY_CODE
AND FM.PRODUCT_CODE IN
#{productCode}
) > 0 THEN '5' ELSE '4' END ,COO_DATE = CURRENT_TIMESTAMP WHERE COMPANY_CODE = #{companyCode} AND SALES_NO = #{salesNo}

UPDATE SALES_DTL DTL SET STATUS = CASE WHEN (SELECT COALESCE(SUM(CASE WHEN FR.STATUS = 'E' THEN 1 ELSE 0 END + CASE WHEN FM.RULE_CONTENTS IS NOT NULL THEN 0 ELSE 1 END), 1) FROM FCR_MST FM LEFT OUTER JOIN FCR_RESULT FR ON FR.FTA_CODE = FM.FTA_CODE AND FR.SALES_NO = FM.SALES_NO AND FR.SALES_SEQ = FM.SALES_SEQ AND FR.DIVISION_CODE = FM.DIVISION_CODE AND FR.COMPANY_CODE = FM.COMPANY_CODE WHERE FM.SALES_NO = DTL.SALES_NO AND FM.DIVISION_CODE = DTL.DIVISION_CODE AND FM.COMPANY_CODE = DTL.COMPANY_CODE AND FM.SALES_SEQ = DTL.SALES_SEQ) > 0 THEN '5' ELSE '4' END ,UPDATE_DATE = CURRENT_TIMESTAMP ,UPDATE_BY = 'MONTHLY_DECISION_PROC' WHERE COMPANY_CODE = #{companyCode} AND SALES_NO = #{salesNo}
AND PRODUCT_CODE IN
#{productCode}

UPDATE FCR_MST
SET    COO_DATE = CURRENT_TIMESTAMP
WHERE  COMPANY_CODE = #{companyCode}
AND    SALES_NO = #{salesNo}

AND    PRODUCT_CODE IN

           #{productCode}
